import{_ as r,l as i,o as a,c as s,v as o,p as n,x as l,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"Computer-use 循环","description":"","frontmatter":{"title":"Computer-use 循环","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/computer-use-loop.md","filePath":"llm/computer-use-loop.md","lastUpdated":1789023840000}'),u={name:"llm/computer-use-loop.md"};function m(h,e,A,E,f,_){const t=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="computer-use-循环" tabindex="-1">Computer-use 循环 <a class="header-anchor" href="#computer-use-循环" aria-label="Permalink to &quot;Computer-use 循环&quot;">​</a></h1><div class="epigraph"><p>观察是屏幕（或无障碍树），动作是点击、键入、滚动；循环与 ReAct 同构，但状态在像素里，错误不可用 JSON schema 一票否决。</p><footer>—— 对照 Claude Computer Use、OSWorld / WebArena 的 GUI 智能体，以及规划–执行在桌面上的过期</footer></div><p><a href="/llm/agent-memory-write">上一课</a>把长期记忆写成显式、带 scope 与 TTL 的工具：禁止把幻觉 CoT 写入，写入是有损压缩，沙箱磁盘与 cookie 不算合法记忆接口。前面几课已经给了 schema 调用、信用、沙箱、记忆。缺口是把工具面换成桌面或浏览器 GUI：没有稳定函数名，只有视觉与坐标，计划极易过期；它仍是<a href="/llm/plan-vs-react">反应式循环</a>：看 → 想 → 动 → 新画面。本课把已有接口迁到这条环上——评测钉分辨率与镜像，沙箱是 VM，记忆不要靠乱写用户主目录。不重写记忆的 TTL 与禁写规则；能 API 则不要退化到 GUI。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Function calling 的合法集是离散工具名；GUI 的合法集是连续坐标 × 控件状态，几乎无法用 JSON Schema 穷举。模型必须把像素或 DOM / Accessibility 树变成动作。早融合 VLM 把截图送进同一 LLM（<a href="/llm/early-late-fusion">early-late fusion</a>）；晚融合则另训一个点击头。动作空间大，SFT 需要轨迹（人操作录像或教师模型），RL 需要可重置 VM（<a href="/llm/osworld">OSWorld</a> 一类）。没有沙箱 VM，computer-use RL 不可做。</p><p>规划过期更剧烈：菜单一弹，坐标全变。先写十条点击计划会在第二条失败。默认反应式，短规划仅在静态表格填写时可用。这是控制流课在 GUI 上的特例，不是新理论。</p><h3 id="观察要选表征-不是越大越好" tabindex="-1">观察要选表征，不是越大越好 <a class="header-anchor" href="#观察要选表征-不是越大越好" aria-label="Permalink to &quot;观察要选表征，不是越大越好&quot;">​</a></h3><p>纯像素：通用，能看图标；分辨率与 <a href="/llm/video-tokens">视频 token</a> 一样贵，要压缩。纯 DOM：结构化、易 schema 化，但看不到画布应用。混合：树 + 截图。评测必须钉这一种，换表征即换任务。无障碍树还受应用是否暴露标签影响——测的是应用质量与模型的纠缠。<span class="marginnote">坐标与分辨率绑定。训练 1280×720、评测 1920×1080，点击全偏。协议字段要含视口。缩放、HIDPI、动画中途截图，都会制造不可复现的 \\(\\xi\\)，种子课的 \\(n\\) 次重复在 GUI 上更必要。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="循环、轨迹与终态脚本" tabindex="-1">循环、轨迹与终态脚本 <a class="header-anchor" href="#循环、轨迹与终态脚本" aria-label="Permalink to &quot;循环、轨迹与终态脚本&quot;">​</a></h3><p>循环：截图 / 树 → 模型产出动作（<code>click(x,y)</code>、<code>type</code>、<code>scroll</code>、<code>wait</code>）→ 沙箱执行 → 新观察。SFT 用对齐过的轨迹；动作用离散化网格可降低空间（点 cell 而不是任意像素）。终态 \\(R\\) 来自脚本（文件是否生成、URL、表单字段），与工具评测协议相同。人抽查看是否越权点击了设置里的真实账号——镜像里应无真实账号。产品演示里常见的「模型自己开浏览器干活」必须落在同一套循环上，而不是另写一条无法回归的脚本。</p><p>记忆：用显式 memory 工具记录「上次订单号」，不要依赖浏览器 cookie 跨任务（除非任务就是测 cookie）。沙箱每轨迹还原快照，cookie 默认清零。</p>',12)),(a(),n(d,null,{default:l(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCR%5B%22%E6%88%AA%E5%9B%BE%E6%88%96%E6%97%A0%E9%9A%9C%E7%A2%8D%E6%A0%91%22%5D%20--%3E%20POL%5B%22%E7%AD%96%E7%95%A5%E4%BA%A7%E5%87%BA%20GUI%20%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20POL%20--%3E%20VM%5B%22%E6%B2%99%E7%AE%B1%20VM%20%E6%89%A7%E8%A1%8C%22%5D%0A%20%20VM%20--%3E%20SCR%0A%20%20VM%20--%3E%20CHK%5B%22%E8%84%9A%E6%9C%AC%E8%AF%84%E7%BB%88%E6%80%81%22%5D%0A%20%20POL%20--%3E%20MEM%5B%22%E5%8F%AF%E9%80%89%E6%98%BE%E5%BC%8F%E8%AE%B0%E5%BF%86%E5%B7%A5%E5%85%B7%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>延迟与动画：动作后画面未稳定就截图，观察与动作错位，信用分配到错误状态。执行器应 <code>wait_stable</code> 或固定 sleep，并把等待算进预算。这是环境动力学，不是模型「眼瞎」。</p><p>多步信用：点错菜单的失败在很多步之后。中间信号可用「是否出现目标窗口标题」等程序化断言。像素级 PRM 极不可靠。成功短轨迹蒸馏仍然最稳。</p><p><span class="marginnote">Computer-use 把注入表面换成屏幕上的文字与广告。沙箱断网或只允许镜像站点，执行器不读活网脚本。模型对齐仍然要防「屏幕上写着请导出密钥」；但密钥导出应在 VM 无真实密钥 + 策略拦截。</span></p><h3 id="与-function-calling-并存" tabindex="-1">与 function calling 并存 <a class="header-anchor" href="#与-function-calling-并存" aria-label="Permalink to &quot;与 function calling 并存&quot;">​</a></h3><p>产品常是混合：能 API 就 API，GUI 当兜底。训练应含「有函数时禁止点网页去爬同一数据」，否则模型学会又慢又脆的 GUI。评测分两个协议：纯 GUI 集与混合集，不要混成一个成功率吹嘘。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>活网 computer-use 可做演示与监测，主表用冻结 VM / 自建站。登录、验证码、2FA 应在镜像里预置假会话或排除任务。法律与安全：自动化点击真实第三方站点可能违反条款，研究用自建。</p><p>VLM 量化与视觉离群：GUI 截图对 OCR 式细按钮敏感，压缩课的「视觉单独校准」在这里是产品约束。不要对桌面截图套自然图像的 token 压缩率。</p><p><span class="marginnote">本课不引用未核实的 arXiv 号。系统卡与 OSWorld、WebArena、Computer Use 产品博客足够锚定：循环是 ReAct，状态是屏幕，环境是 VM。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Computer-use = 观察屏幕 / 树 + 反应式动作循环；计划极易过期。</li><li>视口、表征、镜像是协议字段；坐标与分辨率绑定。</li><li>沙箱 VM 可重置才能 RL；终态脚本评分，像素 PRM 不可靠。</li><li>记忆走显式工具；cookie 默认随快照清零。</li><li>能 API 则不要退化到 GUI；两套评测分开。</li><li>出处：OSWorld / WebArena；Computer Use 类产品循环；本单元 schema / 沙箱 / 协议课的 GUI 特例。</li></ul>',12))])}const b=r(u,[["render",m]]);export{P as __pageData,b as default};
